function getJasperaiTranslation(key, lang) {
  if (jasperaiTranslations[lang] && jasperaiTranslations[lang][key]) {
    return jasperaiTranslations[lang][key];
  }
  if (jasperaiTranslations.en && jasperaiTranslations.en[key]) {
    return jasperaiTranslations.en[key];
  }
  return null;
}

function applyJasperaiTranslations(lang) {
  console.log(`🔥 Applying jasper-ai translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.jasper-ai.') || key.startsWith('review.common.'))) {
      const translation = getJasperaiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} jasper-ai translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyJasperaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyJasperaiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyJasperaiTranslations(currentLang);
}

console.log('✅ jasper-ai i18n loaded');
